func main() {
    var X int
    fmt.Scan(&X)

    var Y int
    fmt.Scan(&Y)

    var Z int
    fmt.Scan(&Z)

    var W int
    fmt.Scan(&W)
	var time int
	for i := 1; i < X + 1; i++ {
		time += Y
		if (i == X) {
			time += W
		} else if (i % Z == 0) {
			time += W * 2
		}
	}

    // fmt.Fprintln(os.Stderr, "Debug messages...")
